package com.labloop.web;
import java.net.URI; import javax.sql.DataSource; import org.springframework.context.annotation.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.jdbc.datasource.DriverManagerDataSource;
@Configuration class DatabaseConfig { @Bean DataSource dataSource(@Value("${DATABASE_URL:}") String value){ DriverManagerDataSource d=new DriverManagerDataSource(); if(value.isBlank()){d.setDriverClassName("org.h2.Driver");d.setUrl("jdbc:h2:mem:labloop;MODE=PostgreSQL;DB_CLOSE_DELAY=-1");d.setUsername("sa");return d;} URI u=URI.create(value);d.setDriverClassName("org.postgresql.Driver");d.setUrl("jdbc:postgresql://"+u.getHost()+":"+(u.getPort()<0?5432:u.getPort())+u.getPath());String[] c=u.getUserInfo().split(":",2);d.setUsername(c[0]);d.setPassword(c.length>1?c[1]:"");return d;} }
